using HRM.Models;using HRM.Models.Recruitment;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;namespace HRM.Api.Data.EntityConfigurations;public sealed class RecruitmentOffersMapping:IEntityTypeConfiguration<RecruitmentOffer>{public void Configure(EntityTypeBuilder<RecruitmentOffer>b){b.ToTable("RM_RecruitmentOffers");b.HasKey(x=>x.Id);b.Property(x=>x.TermsSnapshotJson).HasMaxLength(16000).IsRequired();b.Property(x=>x.Status).HasMaxLength(30).IsRequired();b.Property(x=>x.Version).IsConcurrencyToken();b.HasIndex(x=>x.RecruitmentMeritResultId).IsUnique();b.HasOne<RecruitmentMeritResult>().WithMany().HasForeignKey(x=>x.RecruitmentMeritResultId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Organisation>().WithMany().HasForeignKey(x=>x.OrganisationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<OperationLog>().WithMany().HasForeignKey(x=>x.OperationLogId).OnDelete(DeleteBehavior.Restrict);}}
